d = sys.stdin.read().split()
n, m = int(d[0]), int(d[1])
to = list(range(n + 1))
for i in range(m):
    to[int(d[2 + 2 * i])] = int(d[3 + 2 * i])
INF = 10 ** 9
dist = [INF] * (n + 1)
dist[1] = 0
changed = True
while changed:
    changed = False
    for x in range(1, n):
        if dist[x] < INF:
            for y in range(x + 1, min(x + 6, n) + 1):
                z = to[y]
                if dist[x] + 1 < dist[z]:
                    dist[z] = dist[x] + 1
                    changed = True
print(dist[n] if dist[n] < INF else -1)

